  tasks.append({'id':pid,'depends_on':deps or ['E00'],'allowed_paths':paths,'acceptance':f'tests/acceptance/{pid}.test.mjs','prompt':f'orchestration/prompts/{pid}.md','auto_accept':False,'requires_approval':pid in ['F00','F08']})
